use system.os
use system.fs
use system.collections.array
use system.collections.list

// Largest grid is 512 x 512 cells. The gpu fn signature spells the size as a
// literal because a named constant does not match the buffers' inferred type.
const MAX_CELLS = 262144
const BLOCK_SIZE = 256

// One thread per cell. Reads `src` and writes `dst`, so every cell of a step
// sees the values the previous step left.
gpu fn stencil(src Array<i32, 262144>, dst out Array<i32, 262144>, width i32, height i32, cells i32)
    let i = (kernel.global_idx.x) as i32
    if i < cells
        let x = i % width
        let y = i / width
        // A neighbour outside the grid is the cell itself.
        let left = if x > 0: i - 1 else: i
        let right = if x < width - 1: i + 1 else: i
        let up = if y > 0: i - width else: i
        let down = if y < height - 1: i + width else: i
        dst[i] = (4 * src[i] + src[left] + src[right] + src[up] + src[down]) / 8

fn emit(cur Array<i32, MAX_CELLS>, width int, height int)
    var total = 0
    for row in 0..height
        var parts = List<String>()
        for col in 0..width
            let v = cur[row * width + col]
            total += v as int
            parts.push(f"{v}")
        println(" ".join(parts))
    println(f"SUM {total}")

fn main()
    let args = Args()
    let fs = Fs()
    let text = match fs.read_file(args.element_at(0))
        Result.Ok(t): t
        Result.Err(e): panic(f"cannot read input: {e}")

    // Whitespace of any kind separates the numbers.
    let tokens = text.replace("\n", " ").replace("\r", " ").replace("\t", " ").split(" ")
    var values = List<int>()
    for t in tokens
        if not t.is_empty()
            values.push(t.to_int() ?? 0)

    let width = values.get(0)
    let height = values.get(1)
    let steps = values.get(2)
    let cells = width * height

    var start = Array<i32, MAX_CELLS>()
    for k in 0..cells
        start[k] = values.get(3 + k) as i32

    // Two device buffers ping-pong: even steps read `a` and write `b`, odd
    // steps the reverse. A step never reads the buffer it writes.
    gpu var a = start
    gpu var b = Array<i32, MAX_CELLS>()
    let grid = (cells + BLOCK_SIZE - 1) / BLOCK_SIZE
    for s in 0..steps
        if s % 2 == 0
            stencil(a, b, width as i32, height as i32, cells as i32).launch(Dim3(grid, 1, 1), Dim3(256, 1, 1))
        else
            stencil(b, a, width as i32, height as i32, cells as i32).launch(Dim3(grid, 1, 1), Dim3(256, 1, 1))

    if steps % 2 == 0
        let h = a
        emit(h, width, height)
    else
        let h = b
        emit(h, width, height)

